const runSeeder = async () => {
  try {
    console.log('Connecting to database for seeding...');
    await mongoose.connect(MONGO_URI);
    console.log('Connected to MongoDB.');

    // Clear existing data
    console.log('Clearing old collections...');
    await Restaurant.deleteMany({});
    await Booking.deleteMany({});
    await Offer.deleteMany({});
    await Settlement.deleteMany({});
    await Payment.deleteMany({});
    await User.deleteMany({});
    console.log('Collections cleared.');

    // Insert seeds
    console.log('Seeding restaurants...');
    const seen = new Set();
    const filtered = seedRestaurants.filter(r => {
      if (seen.has(r.id)) return false;
      const keep = r.id <= 10 || (r.id >= 31 && r.id <= 50) || r.id === 999;
      if (keep) seen.add(r.id);
      return keep;
    });
    await Restaurant.insertMany(filtered);
    
    console.log('Seeding bookings...');
    await Booking.insertMany(seedBookings);

    console.log('Seeding offers...');
    await Offer.insertMany(seedOffers);

    console.log('Seeding settlements...');
    await Settlement.insertMany(seedSettlements);

    console.log('Seeding users...');
    const salt = await bcrypt.genSalt(10);
    const hashedPassword = await bcrypt.hash('password123', salt);
    await User.insertMany([
      {
        email: 'aayushjadhav05128@gmail.com',
        password: hashedPassword,
        role: 'admin',
        restaurantId: null
      },
      {
        email: 'owner1@vidyarthibhavan.com',
        password: hashedPassword,
        role: 'owner',
        restaurantId: 1
      },
      {
        email: 'owner2@toit.com',
        password: hashedPassword,
        role: 'owner',
        restaurantId: 2
      },
      {
        email: 'owner3@truffles.com',
        password: hashedPassword,
        role: 'owner',
        restaurantId: 3
      }
    ]);

    console.log('Database seeded successfully!');
    process.exit(0);
  } catch (error) {
    console.error('Error seeding database:', error);
    process.exit(1);
  }
};

runSeeder();
